// SsidDescriptor is the list descriptor callers hand to a protocol library.
func SsidDescriptor() yang.ListDescriptor[Ssid, SsidKey] {
	return yang.ListDescriptor[Ssid, SsidKey]{
		Codec: yang.StructRowCodec(SsidSchema, func(r *Ssid) SsidKey {
			var k SsidKey
			if r.Name != nil {
				k.Name = *r.Name
			}
			return k
		}),
		Path: yang.JoinPath(yang.In(moduleOpenconfigWifiMAC, "ssids", "ssid")),
	}
}

// ClientKey is Client's row identity (ancestor keys in canonical form).
